import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';
import 'package:flutter/services.dart';

/// Android previews are generated by the installed widget's own RemoteViews
/// renderer. The Flutter composition remains a fallback on other platforms.
class NativeWidgetPreview extends StatefulWidget {
  const NativeWidgetPreview({
    super.key,
    required this.type,
    required this.config,
    required this.snapshot,
    required this.width,
    required this.height,
    required this.child,
  });
  final String type;
  final Map<String, dynamic> config, snapshot;
  final double width, height;
  final Widget child;
  @override
  State<NativeWidgetPreview> createState() => _NativeWidgetPreviewState();
}

class _NativeWidgetPreviewState extends State<NativeWidgetPreview> {
  String? _key;
  Future<Uint8List?>? _image;
  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    _load();
  }

  @override
  void didUpdateWidget(NativeWidgetPreview oldWidget) {
    super.didUpdateWidget(oldWidget);
    _load();
  }

  void _load() {
    if (kIsWeb || defaultTargetPlatform != TargetPlatform.android) return;
    final snapshot = Map<String, dynamic>.from(widget.snapshot)
      ..remove('updatedAt');
    final args = {
      'type': widget.type,
      'config': jsonEncode(widget.config),
      'snapshot': jsonEncode(snapshot),
      'width': widget.width,
      'height': widget.height,
      'fontScale': MediaQuery.textScalerOf(context).scale(14) / 14,
      'dark': MediaQuery.platformBrightnessOf(context) == Brightness.dark,
    };
    final key = jsonEncode(args);
    if (key == _key) return;
    _key = key;
    // The renderer still needs a valid freshness timestamp; exclude it only from the key.
    args['snapshot'] = jsonEncode(widget.snapshot);
    _image = const MethodChannel('savetrack/home_widgets')
        .invokeMethod<Uint8List>('preview', args)
        .catchError((Object _) => null);
  }

  @override
  Widget build(BuildContext context) => FutureBuilder<Uint8List?>(
    key: ValueKey(_key),
    future: _image,
    builder: (context, result) => result.data == null
        ? widget.child
        : Image.memory(
            result.data!,
            width: widget.width,
            height: widget.height,
            fit: BoxFit.contain,
            gaplessPlayback: true,
            semanticLabel: '${widget.type} native widget preview',
          ),
  );
}
